insert into public.couple_movie_cache(key,data,updated_at)values('detail:246966',$_movie_${"detailMovie":{"availableEpisodes":0,"awardUrl":"","backgroundColor":"#401D1D","bingeWatch":0,"bingeWatchst":0,"cat":"动作,剧情,犯罪","comScorePersona":false,"commented":false,"dir":"查德·斯塔赫斯基","distributions":[{"movieScoreLevel":"9-10分","proportion":"--"},{"movieScoreLevel":"5-8分","proportion":"--"},{"movieScoreLevel":"1-4分","proportion":"--"}],"dra":"风靡全球的动作IP《疾速追杀》，枪斗暴力美学传奇之作！“杀神”基努·里维斯为一条狗血洗黑帮帝国，狠！暴！爽！\n\n丧妻之后，约翰·威克（基努·里维斯 饰）只剩妻子留下的爱犬黛西以及陪伴自己多年的福特老爷车。然而一群黑帮恶少闯入家中抢走爱车，更残忍杀死了黛西，彻底踏碎了约翰最后的底线。带头者正是黑帮大佬维格·塔拉索夫的儿子。直到维格得知儿子招惹的人是谁，才意识到大祸临头——约翰并不是普通人，而是令整个杀手世界闻风丧胆的传奇杀神“夜魔”。如今约翰重出江湖，穿上黑西装，为枪械上膛，从车库杀到夜店，从教堂杀到码头，誓要孤身杀穿整个黑帮帝国为黛西复仇。枪枪爆头，招招索命，一条狗引发的血债，最终会用多少人的命来偿还？","dur":102,"egg":false,"enm":"John Wick","episodeDur":101,"episodes":0,"fra":"美国,美国,捷克,丹麦,以色列,新加坡,泰国,加拿大,芬兰,美国,越南,法国,菲律宾,澳大利亚,中国香港,伊拉克,科威特,黎巴嫩,墨西哥,保加利亚,冰岛,罗马尼亚,瑞典,中国台湾,巴基斯坦,匈牙利,马来西亚,葡萄牙,爱沙尼亚,印度,立陶宛,拉脱维亚,荷兰,比利时,巴西,新西兰,土耳其,阿塞拜疆,阿尔巴尼亚,哈萨克斯坦,Republic of North Macedonia,波兰,乌克兰,智利,巴拉圭,南非,哥伦比亚,秘鲁,巴拿马,俄罗斯,斯洛文尼亚,阿根廷,韩国,瑞士,意大利,德国,挪威,希腊,乌拉圭,英国,爱尔兰,日本,西班牙","frt":"2014-09-19 00:00:00,2014-10-13 00:00:00,2014-10-23 00:00:00,2014-10-23 00:00:00,2014-10-23 00:00:00,2014-10-23 00:00:00,2014-10-23 00:00:00,2014-10-24 00:00:00,2014-10-24 00:00:00,2014-10-24 00:00:00,2014-10-24 00:00:00,2014-10-29 00:00:00,2014-10-29 00:00:00,2014-10-30 00:00:00,2014-10-30 00:00:00,2014-10-30 00:00:00,2014-10-30 00:00:00,2014-10-30 00:00:00,2014-10-30 00:00:00,2014-10-31 00:00:00,2014-10-31 00:00:00,2014-10-31 00:00:00,2014-10-31 00:00:00,2014-10-31 00:00:00,2014-11-07 00:00:00,2014-11-13 00:00:00,2014-11-13 00:00:00,2014-11-13 00:00:00,2014-11-14 00:00:00,2014-11-14 00:00:00,2014-11-14 00:00:00,2014-11-14 00:00:00,2014-11-20 00:00:00,2014-11-26 00:00:00,2014-11-27 00:00:00,2014-11-27 00:00:00,2014-11-28 00:00:00,2014-12-03 00:00:00,2014-12-04 00:00:00,2014-12-04 00:00:00,2014-12-04 00:00:00,2014-12-05 00:00:00,2014-12-11 00:00:00,2014-12-18 00:00:00,2014-12-19 00:00:00