insert into public.couple_movie_cache(key,data,updated_at)values('detail:1586199',$_movie_${"detailMovie":{"availableEpisodes":0,"awardUrl":"","backgroundColor":"#1D4040","bingeWatch":0,"bingeWatchst":0,"cat":"惊悚,剧情,科幻","comScorePersona":false,"commented":false,"dir":"扎克·克雷格","distributions":[{"movieScoreLevel":"9-10分","proportion":"--"},{"movieScoreLevel":"5-8分","proportion":"--"},{"movieScoreLevel":"1-4分","proportion":"--"}],"dra":"时隔九年，《生化危机》系列重返内地大银幕，生化异种肆虐，重启噩梦之源！“鬼才导演”扎克·克雷格纯血惊悚新作，准备好迎接这场极限求生挑战了吗？\n医疗速递员布莱恩（奥斯汀·艾布拉姆斯 饰）接到一项紧急委托，奉命奔赴浣熊市。然而派送途中却意外连连，让他猝不及防地深陷一场生化浩劫：变异恶犬疯狂扑杀，嗜血生物接连现身，未知病毒迅速蔓延，导致全城彻底失控……\n仅有一人、一枪、寥寥数发子弹的布莱恩，孤身穿行异种肆虐的城市，每向前行进一步，都有更加致命的下一关在等待着他。惊魂血夜，一个毫无主角光环的普通人，究竟能否冲破层层死局，活过这个疯狂失控的夜晚？而他所派送的神秘包裹，又与这场致命危机有着怎样的关联？\n（友情提示：未成年人谨慎选择观看）","dur":94,"egg":false,"enm":"Resident Evil","episodeDur":94,"episodes":0,"filmAlias":"生化危机 重启版,恶灵古堡：爆发夜,生化危机0,Resident Evil 0,Resident Evil: The Umbrella Chronicles","fra":"美国,中国香港","frt":"2026-09-18,2026-09-17","globalReleased":true,"guideToWish":false,"id":1586199,"img":"https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e3d6c8b5294fa46776d99a3218655e.png?imageMogr2/quality/80","latestEpisode":0,"modcsSt":false,"movieExtraVO":{"envelope":{"buttonContent":"云包场","schemaUrl":"maoyan://maoyan.com/mrn?mrn_biz=movie&mrn_entry=moviechannel-makeabook&mrn_component=moviechannel-makeabook&url=https%3A%2F%2Fm.maoyan.com%2Fcharter%2Fbooking%3Fid%3D149&tab=online&movieId=1586199"}},"movieType":0,"multiPub":true,"musicNum":0,"nm":"生化危机：爆发夜","onSale":true,"onlinePlay":false,"orderSt":0,"oriLang":"英语,国语","photos":["https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e25c8d39a138d3e0a86c23b567ccd4.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e3d6c8b5294fa46776d99a3218655e.png?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e3d6c8bfcf45c29c8830ea3bd05ccf.png?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e3d6e32