insert into public.couple_movie_cache(key,data,updated_at)values('detail:1599810',$_movie_${"detailMovie":{"availableEpisodes":0,"awardUrl":"","backgroundColor":"#401D1D","bingeWatch":0,"bingeWatchst":0,"cat":"恐怖,惊悚,悬疑","comScorePersona":false,"commented":false,"dir":"徐俊","distributions":[{"movieScoreLevel":"9-10分","proportion":"--"},{"movieScoreLevel":"5-8分","proportion":"--"},{"movieScoreLevel":"1-4分","proportion":"--"}],"dra":"影片讲述民国年间，永夜诡镇阴森可怖，阴阳路有进无出，镇民死逃殆尽，却有访客为睹雪新娘冒死前来——她冰肌胜雪、唇红似血，不敬者必见“红如鲜血、白如骨骸”的惨状。镇中避祸规矩：供糯米血饭、燃梅花香摆锁魂阵、跨旺火盆躲进阴阳轩。\n\n阴阳轩内更邪：于掌柜讲“尸变借魂”诡事，江大厨骨汤飘腥气；阳客有热汤暖身，阴魂有纸人侍奉，后堂朱漆宝棺虚位以待。顾梦寒携红衣新娘躲入，仍难逃劫数：催命刀破空，纸人骤燃现鬼影；雪打招魂幡似魂魄挣命，棺木晃动，三丈显道神睁眼喝问：“你可知罪？”影片融合多重中式民俗元素，将诡镇神秘与惊悚交织，营造极致恐怖悬疑氛围，力求给观众渗入骨髓的恐怖体验。","dur":92,"egg":false,"enm":"THE RED COFFIN OF QIN MANOR","episodeDur":93,"episodes":0,"globalReleased":true,"guideToWish":false,"id":1599810,"img":"https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a3e7ea401e88b07ad026bfea82ca43.jpg?imageMogr2/quality/80","latestEpisode":0,"modcsSt":false,"movieExtraVO":{"envelope":{"buttonContent":"云包场","schemaUrl":"maoyan://maoyan.com/mrn?mrn_biz=movie&mrn_entry=moviechannel-makeabook&mrn_component=moviechannel-makeabook&url=https%3A%2F%2Fm.maoyan.com%2Fcharter%2Fbooking%3Fid%3D149&tab=online&movieId=1599810"}},"movieType":0,"multiPub":false,"musicNum":0,"nm":"阴阳路惊魂","onSale":true,"onlinePlay":false,"orderSt":0,"oriLang":"国语","photos":["https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a3e715d80146cb474bf6596e957b42.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a3e7ea401e88b07ad026bfea82ca43.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a8b077e5b287f07dc9ac5ae8e20dee.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a7f077e5be79a13f25a23221547c87.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589ac8b8d3b24e80141ac6efa341190e5.jpg?imageMogr2/thumbn