insert into public.couple_movie_cache(key,data,updated_at)values('detail:1604748',$_movie_${"detailMovie":{"availableEpisodes":0,"awardUrl":"","backgroundColor":"#594228","bingeWatch":0,"bingeWatchst":0,"cat":"喜剧,家庭","comScorePersona":false,"commented":false,"dir":"沈春阳","distributions":[{"movieScoreLevel":"9-10分","proportion":"--"},{"movieScoreLevel":"5-8分","proportion":"--"},{"movieScoreLevel":"1-4分","proportion":"--"}],"dra":"小沈阳、沈春阳搭档贾冰、于洋、魏翔、梁龙、许君聪等喜剧熟面孔排队逗你乐！全家出动，来影院嘎嘎乐呵就完事儿了！\n\n同在一个屋檐下，日子却过得没滋没味。沈默（小沈阳 饰）和尤天意（沈春阳 饰）这对老夫老妻，究竟是怎么硬生生把N年婚姻，熬成了“对抗路”上的极限拉扯？！！！\n章盖了！表填了！离婚申请递交了！曾经的感情耗成了寡淡的白开水，沟通基本靠吼，相处不得不苟，一把同花顺眼看要打成稀巴烂，不如痛痛快快各自清闲。\n前脚刚要潇洒转头，谁料后脚一场奇葩意外猝不及防地兜头砸下，硬生生把两人又给原地“焊死”！\n乏善可陈的日子突然脱了轨，啼笑皆非的状况接踵而来，两人被迫在这场荒诞闹剧中重新审视彼此，也再次爆发出那句经典的灵魂拷问：“你到底什么意思？”“我没什么意思！”——这场离谱的遭遇，究竟能不能让这段婚姻焕发出点儿新“意思”……","dur":106,"egg":false,"enm":"MR. & MRS. PARDON","episodeDur":106,"episodes":0,"fra":"美国,加拿大,澳洲,新西兰","frt":"2026-10-16,2026-10-16,2026-10-15,2026-10-22","globalReleased":true,"guideToWish":false,"id":1604748,"img":"https://p0.pipi.cn/mediaplus/friday_image_fe/e429586ebf83cb5c296cb42d58b63c2824575.jpg?imageMogr2/quality/80","latestEpisode":0,"modcsSt":false,"movieExtraVO":{"envelope":{"buttonContent":"云包场","schemaUrl":"maoyan://maoyan.com/mrn?mrn_biz=movie&mrn_entry=moviechannel-makeabook&mrn_component=moviechannel-makeabook&url=https%3A%2F%2Fm.maoyan.com%2Fcharter%2Fbooking%3Fid%3D149&tab=online&movieId=1604748"}},"movieType":0,"multiPub":true,"musicNum":0,"nm":"什么意思夫妇","onSale":true,"onlinePlay":false,"orderSt":0,"oriLang":"普通话","photos":["https://p0.pipi.cn/mediaplus/friday_image_fe/e429586ebf83cb5c296cb42d58b63c2824575.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429586e52952972a94ea9eb6890f4eabbae3.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a7f05c21fae77e1b9763101b844d78.jpg?imageMogr2/thumbnail/2500x2500%3E","https://p0.pipi.cn/mediaplus/friday_image_fe/e429589a7f06e3fcf44a1877f73005e83fbd