create or replace function public._couple_movie_payload(p_stale boolean default false)
returns jsonb language sql security definer set search_path=public,pg_temp as $$
select jsonb_build_object('source','maoyan','data',coalesce((select jsonb_agg(coalesce(d.data->'detailMovie','{}'::jsonb)||item order by ord)from jsonb_array_elements(c.data->'movieList')with ordinality as entries(item,ord) left join public.couple_movie_cache d on d.key='detail:'||(item->>'id')),'[]'::jsonb),'updatedAt',c.updated_at,'stale',p_stale)
from public.couple_movie_cache c where c.key='chart';$$;
revoke all on function public._couple_movie_payload(boolean)from public,anon,authenticated;

create or replace function public.get_couple_movies()
returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$
declare v_status integer;v_content text;v_data jsonb;v_last timestamptz;
begin
 select updated_at into v_last from public.couple_movie_cache where key='chart';
 if v_last>now()-interval '6 hours'then return public._couple_movie_payload(false);end if;
 if not pg_try_advisory_xact_lock(hashtextextended('little-days-movie-chart',0))then return public._couple_movie_payload(true);end if;
 begin
  select status,content into v_status,v_content from extensions.http_get('https://m.maoyan.com/ajax/movieOnInfoList');
  if v_status<>200 then raise exception 'upstream unavailable';end if;
  v_data:=v_content::jsonb;
  if jsonb_typeof(v_data->'movieList')<>'array' or jsonb_array_length(v_data->'movieList')=0 then raise exception 'empty movie chart';end if;
  insert into public.couple_movie_cache(key,data,updated_at)values('chart',jsonb_build_object('movieList',v_data->'movieList'),clock_timestamp())on conflict(key)do update set data=excluded.data,updated_at=excluded.updated_at;
 exception when others then return public._couple_movie_payload(true);end;
 return public._couple_movie_payload(false);
end;$$;
revoke all on function public.get_couple_movies()from public;
grant execute on function public.get_couple_movies()to anon,authenticated;

create or replace function public.get_couple_movie_detail(p_id integer)
returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$
declare v_status integer;v_content text;v_data jsonb;v_last timestamptz;v_cached jsonb;
begin
 if p_id<1 or p_id>100000000 then raise exception 'invalid movie id';end if;
 select data,updated_at into v_cached,v_last from public.couple_movie_cache where key='detail:'||p_id::text;
 if v_last>now()-interval '24 hours'then return v_cached->'detailMovie';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('little-days-movie-detail:'||p_id::text,0))then return v_cached->'detailMovie';end if;
 begin
  select status,content into v_status,v_content from extensions.http_get('https://m.maoyan.com/ajax/detailmovie?movieId='||p_id::text);
  if v_status<>200 then raise exception 'upstream unavailable';end if;
  v_data:=v_content::jsonb;
  if (v_data->'detailMovie'->>'id')::integer is distinct from p_id then raise exception 'invalid movie';end if;
  insert into public.couple_movie_cache(key,data,updated_at)values('detail:'||p_id::text,v_data,clock_timestamp())on conflict(key)do update set data=excluded.data,updated_at=excluded.updated_at;
  return v_data->'detailMovie';
 exception when others then return v_cached->'detailMovie';end;
end;$$;
revoke all on function public.get_couple_movie_detail(integer)from public;
grant execute on function public.get_couple_movie_detail(integer)to anon,authenticated;
notify pgrst,'reload schema';
commit;
select jsonb_array_length(public.get_couple_movies()->'data')as movies;
